// =============================================================================
// tb_softmax_unit.v  –  Standalone testbench for softmax_unit.sv
//
// Reads test vectors and golden reference from text files generated by
// gen_softmax_golden.py (run that script first to create the .txt files).
//
// File layout (one hex value per line, row-major, all test cases packed):
//   softmax_sij.txt       N_TESTS × Br × Bc   Q8.8  input Sij
//   softmax_golden_m.txt  N_TESTS × Br         Q8.8  expected m_tilde
//   softmax_golden_p.txt  N_TESTS × Br × Bc    Q8.8  expected P_tilde
//   softmax_golden_l.txt  N_TESTS × Br         32-bit expected l_tilde
//
// Compile & run from the FlashAttention/ directory:
//   iverilog -g2005-sv -o sim_softmax.out tb_softmax_unit.v \
//       softmax_unit.sv exp.sv && vvp sim_softmax.out
// =============================================================================

module tb_softmax_unit;

    // =========================================================================
    // Parameters  (must match softmax_unit instantiation)
    // =========================================================================
    parameter integer Br     = 4;
    parameter integer Bc     = 8;
    parameter integer DATA_W = 16;   // Q8.8
    parameter integer ACC_W  = 32;

    localparam integer N_TESTS = 8;  // number of test cases (matches gen script)

    // =========================================================================
    // Input / reference file paths
    // =========================================================================
    parameter SIJ_FILE = "softmax_sij.txt";
    parameter M_FILE   = "softmax_golden_m.txt";
    parameter P_FILE   = "softmax_golden_p.txt";
    parameter L_FILE   = "softmax_golden_l.txt";

    // =========================================================================
    // DUT ports (regs drive the combinational inputs)
    // =========================================================================
    reg  signed [DATA_W-1:0] Sij     [0:Br-1][0:Bc-1];

    wire signed [DATA_W-1:0] m_tilde [0:Br-1];
    wire signed [DATA_W-1:0] P_tilde [0:Br-1][0:Bc-1];
    wire signed [ACC_W-1:0]  l_tilde [0:Br-1];

    // =========================================================================
    // DUT
    // =========================================================================
    softmax_unit #(
        .Br    (Br),
        .Bc    (Bc),
        .DATA_W(DATA_W),
        .ACC_W (ACC_W)
    ) dut (
        .Sij    (Sij),
        .m_tilde(m_tilde),
        .P_tilde(P_tilde),
        .l_tilde(l_tilde)
    );

    // =========================================================================
    // Flat storage for $readmemh  (N_TESTS × Br × Bc elements)
    // =========================================================================
    reg [DATA_W-1:0] sij_flat [0:N_TESTS*Br*Bc-1];
    reg [DATA_W-1:0] m_ref    [0:N_TESTS*Br-1];
    reg [DATA_W-1:0] p_ref    [0:N_TESTS*Br*Bc-1];
    reg [ACC_W-1:0]  l_ref    [0:N_TESTS*Br-1];

    // =========================================================================
    // Test loop variables
    // =========================================================================
    integer tc, r, c, base_rc, base_r;
    integer m_err, p_err, l_err;
    integer total_errors;
    integer m_diff, p_diff, l_diff;
    reg [DATA_W-1:0] got_m, exp_m, got_p, exp_p;
    reg [ACC_W-1:0]  got_l, exp_l;

    // =========================================================================
    // Main test sequence
    // =========================================================================
    initial begin
        // ------------------------------------------------------------------
        // 1. Load files
        // ------------------------------------------------------------------
        $readmemh(SIJ_FILE, sij_flat);
        $readmemh(M_FILE,   m_ref);
        $readmemh(P_FILE,   p_ref);
        $readmemh(L_FILE,   l_ref);

        $display("==============================================");
        $display(" softmax_unit testbench");
        $display(" Br=%0d  Bc=%0d  DATA_W=%0d  ACC_W=%0d  N_TESTS=%0d",
                 Br, Bc, DATA_W, ACC_W, N_TESTS);
        $display("==============================================");

        total_errors = 0;

        // ------------------------------------------------------------------
        // 2. Iterate over test cases
        // ------------------------------------------------------------------
        for (tc = 0; tc < N_TESTS; tc = tc + 1) begin

            // Unpack flat sij_flat into 2D Sij reg
            base_rc = tc * Br * Bc;
            for (r = 0; r < Br; r = r + 1)
                for (c = 0; c < Bc; c = c + 1)
                    Sij[r][c] = sij_flat[base_rc + r*Bc + c];

            // Let combinational logic settle
            #1;

            // ---------------------------------------------------------------
            // 3. Check outputs
            // ---------------------------------------------------------------
            m_err = 0;
            p_err = 0;
            l_err = 0;
            base_r  = tc * Br;
            base_rc = tc * Br * Bc;

            $display("----------------------------------------------");
            $display(" TC%0d", tc);

            // m_tilde
            for (r = 0; r < Br; r = r + 1) begin
                got_m = m_tilde[r];
                exp_m = m_ref[base_r + r];
                m_diff = $signed(got_m) - $signed(exp_m);
                if (m_diff < 0) m_diff = -m_diff;
                $display("  m_tilde[%0d]  got=%04h (%7.3f)  exp=%04h (%7.3f)%s",
                    r,
                    got_m, $itor($signed(got_m)) / 256.0,
                    exp_m, $itor($signed(exp_m)) / 256.0,
                    (m_diff != 0) ? "  <-- FAIL" : "");
                if (m_diff != 0) m_err = m_err + 1;
            end

            // P_tilde
            for (r = 0; r < Br; r = r + 1) begin
                for (c = 0; c < Bc; c = c + 1) begin
                    got_p = P_tilde[r][c];
                    exp_p = p_ref[base_rc + r*Bc + c];
                    p_diff = $signed(got_p) - $signed(exp_p);
                    if (p_diff < 0) p_diff = -p_diff;
                    $display("  P_tilde[%0d][%0d] got=%04h (%6.4f)  exp=%04h (%6.4f)%s",
                        r, c,
                        got_p, $itor($signed(got_p)) / 256.0,
                        exp_p, $itor($signed(exp_p)) / 256.0,
                        (p_diff != 0) ? "  <-- FAIL" : "");
                    if (p_diff != 0) p_err = p_err + 1;
                end
            end

            // l_tilde
            for (r = 0; r < Br; r = r + 1) begin
                got_l = l_tilde[r];
                exp_l = l_ref[base_r + r];
                l_diff = $signed(got_l) - $signed(exp_l);
                if (l_diff < 0) l_diff = -l_diff;
                $display("  l_tilde[%0d]  got=%08h (%8.3f)  exp=%08h (%8.3f)%s",
                    r,
                    got_l, $itor($signed(got_l)) / 256.0,
                    exp_l, $itor($signed(exp_l)) / 256.0,
                    (l_diff != 0) ? "  <-- FAIL" : "");
                if (l_diff != 0) l_err = l_err + 1;
            end

            if (m_err + p_err + l_err == 0)
                $display("  --> TC%0d PASS", tc);
            else
                $display("  --> TC%0d FAIL  (m:%0d  P:%0d  l:%0d mismatches)",
                         tc, m_err, p_err, l_err);

            total_errors = total_errors + m_err + p_err + l_err;
        end

        // ------------------------------------------------------------------
        // 4. Final summary
        // ------------------------------------------------------------------
        $display("==============================================");
        if (total_errors == 0)
            $display("PASS  –  all %0d test cases correct", N_TESTS);
        else
            $display("FAIL  –  %0d total mismatches across %0d test cases",
                     total_errors, N_TESTS);
        $display("==============================================");

        $finish;
    end

endmodule
